/**
 * ID formatting utilities.
 *
 * Responsible for applying a prefix to a generated or accepted request ID.
 * Also validates that the prefix itself cannot introduce unsafe header values.
 */

/** Characters allowed in a prefix. */
const PREFIX_PATTERN = /^[a-zA-Z0-9_-]+$/;

/**
 * Validate a configured prefix string.
 *
 * @param {string} prefix
 * @throws {TypeError} when the prefix contains disallowed characters.
 */
export function assertValidPrefix(prefix) {
  if (typeof prefix !== "string") {
    throw new TypeError(
      `[@mohammed_kashif/requestid] options.prefix must be a string, got: ${typeof prefix}`
    );
  }

  if (prefix !== "" && !PREFIX_PATTERN.test(prefix)) {
    throw new TypeError(
      `[@mohammed_kashif/requestid] options.prefix contains disallowed characters. ` +
      `Use only: a-z A-Z 0-9 _ -`
    );
  }
}

/**
 * Validate a header name string.
 * HTTP header field-names must conform to RFC 7230 §3.2.
 *
 * @param {string} name
 * @throws {TypeError}
 */
export function assertValidHeaderName(name) {
  if (typeof name !== "string" || name.trim() === "") {
    throw new TypeError(
      `[@mohammed_kashif/requestid] options.headerName must be a non-empty string`
    );
  }

  // RFC 7230 token characters
  if (!/^[!#$%&'*+\-.^_`|~a-zA-Z0-9]+$/.test(name)) {
    throw new TypeError(
      `[@mohammed_kashif/requestid] options.headerName "${name}" is not a valid HTTP header name`
    );
  }
}

/**
 * Apply a prefix to a request ID.
 *
 * @param {string} id
 * @param {string} prefix
 * @returns {string}
 */
export function applyPrefix(id, prefix) {
  return prefix ? `${prefix}_${id}` : id;
}
